function coord(i){return cols[i%9]+(9-Math.floor(i/9));}
function neigh(i){const a=[];if(i%9)a.push(i-1);if(i%9<8)a.push(i+1);if(i>=9)a.push(i-9);if(i<72)a.push(i+9);return a;}
